# >>> STATIC
_static_run_node_modules_dir() {
    cat <<-'ARGCEOF'
	auto	create a local node_modules directory and install npm packages into it
	manual	use the existing local node_modules directory, do not modify it
	none	do not use a local node_modules directory; resolve npm packages from the global cache
ARGCEOF
}

_static_watch_node_modules_dir() {
    cat <<-'ARGCEOF'
	auto	create a local node_modules directory and install npm packages into it
	manual	use the existing local node_modules directory, do not modify it
	none	do not use a local node_modules directory; resolve npm packages from the global cache
ARGCEOF
}

_static_serve_node_modules_dir() {
    cat <<-'ARGCEOF'
	auto	create a local node_modules directory and install npm packages into it
	manual	use the existing local node_modules directory, do not modify it
	none	do not use a local node_modules directory; resolve npm packages from the global cache
ARGCEOF
}

_static_eval_node_modules_dir() {
    cat <<-'ARGCEOF'
	auto	create a local node_modules directory and install npm packages into it
	manual	use the existing local node_modules directory, do not modify it
	none	do not use a local node_modules directory; resolve npm packages from the global cache
