# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_allow_sys() {
    printf '%s\n' \
        hostname osRelease osUptime loadavg networkInterfaces \
        systemMemoryInfo uid gid cpus homedir execPath osVersion osArch stat
}

_choice_arch() {
    printf '%s\n' arm arm64 ia32 mips mipsel ppc ppc64 s390 s390x x64
}

_choice_audit_level() {
    printf '%s\n' low moderate high critical
}

_choice_backend() {
    printf '%s\n' webview cef raw
}

_choice_build_timeout() {
    printf '%s\n' 5 10 15 20 25 30
}

_choice_bump_increment() {
    printf '%s\n' major minor patch premajor preminor prepatch prerelease
}

_choice_check() {
    printf '%s\n' all local remote
}

_choice_command() {
    _argc_util_comp_command
}

_choice_compress() {
    printf '%s\n' xz lzma zstd
}

_choice_dependency() {
    local config
    config="$(_argc_util_path_search_parent deno.json deno.jsonc package.json)"
    [[ -n $config ]] || return 0
    case "$config" in
    */package.json)
        jq -b -r '((.dependencies // {}) + (.devDependencies // {}) + (.peerDependencies // {}) + (.optionalDependencies // {})) | keys[]' "$config" 2>/dev/null
        ;;
    *)
        jq -b -r '(.imports // {}) | keys[]' "$config" 2>/dev/null
        ;;
    esac
}

_choice_engine() {
    printf '%s\n' v8 quickjs
}

_choice_env_name() {
    compgen -e
}

_choice_ext() {
    printf '%s\n' ts tsx js jsx mts mjs cts cjs
}

_choice_installed_bin() {
    local root="${DENO_INSTALL_ROOT:-$HOME/.deno}/bin" bin
    [[ -d $root ]] || return 0
    for bin in "$root"/*; do
        [[ -f $bin ]] || continue
        bin="${bin##*/}"
        printf '%s\n' "${bin%.exe}"
    done
}

_choice_log_level() {
    printf '%s\n' trace debug info
}

_choice_os() {
    printf '%s\n' aix android darwin freebsd linux openbsd sunos win32
}

_choice_path() {
    _argc_util_comp_path
}

_choice_permission_set() {
    local config
    config="$(_argc_util_path_search_parent deno.json deno.jsonc)"
    [[ -n $config ]] || return 0
    jq -b -r '(.permissions // {}) | keys[] | select(. != "default")' "$config" 2>/dev/null
}

_choice_reporter() {
    printf '%s\n' pretty dot junit tap
}

_choice_shell() {
    printf '%s\n' bash fish powershell zsh fig
}

_choice_target() {
    printf '%s\n' \
        x86_64-unknown-linux-gnu \
        aarch64-unknown-linux-gnu \
        x86_64-pc-windows-msvc \
        aarch64-pc-windows-msvc \
        x86_64-apple-darwin \
        aarch64-apple-darwin
}

_choice_task() {
    NO_COLOR=1 deno task 2>/dev/null | sed -n 's/^- //p'
}

_choice_uninstall() {
    _choice_dependency
    _choice_installed_bin
}

_choice_workspace() {
    local config
    config="$(_argc_util_path_search_parent deno.json deno.jsonc)"
    [[ -n $config ]] || return 0
    jq -b -r '
        (.workspace // empty) |
        if type == "array" then .[]
        elif type == "object" then (.members // [])[]
        else empty end
    ' "$config" 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
